            var core=game.CartLines.Single();Check(game.EditNativeCartPurchase(core,JsonUtility.ToJson(core),car.instanceId,false,null,2,true,Array.Empty<string>())&&core.quantity==2,"Prepared inline quantity edits remain valid and retain the reviewed installation");yield return new WaitForSecondsRealtime(.3f);yield return CartClick(input,"cartEdit:"+NativeMenuShell.NativeCartRowKey(core));yield return Click(input,"dialogApply");Check(shell.Root.Q("blockPreparationMode:Manual")!=null&&shell.Root.Q<Button>("dialogAddplan").enabledSelf,"Editing a prepared core reopens component review rather than bypassing it");yield return Click(input,"dialogAddplan");
            string engine=game.Profile.SelectedCar.engineAssemblyId;yield return Click(input,"cartCheckout");yield return Click(input,"dialogConfirm");Check(game.Profile.SelectedCar.engineAssemblyId==engine&&game.Profile.parts.Any(i=>i.definitionId==definition&&i.ownerId==engine)&&game.CartCount==0,"One checkout installs the block inside the retained current engine");yield return Click(input,"cartBack");
            yield return Click(input,"partsSource:Inventory");yield return WaitParts();var owned=shell.PartBrowser.Entries.First(e=>e.Source=="Owned"&&e.Part?.location==PartLocation.Inventory&&e.Definition.category==PartCategory.CylinderBlock&&e.Definition.id!=definition);shell.Root.Q<ScrollView>("partsScroll").ScrollTo(PartCard("partCard:"+owned.Id));yield return new WaitForSecondsRealtime(.15f);yield return Click(input,"partCard:"+owned.Id);string movedBefore=JsonUtility.ToJson(game.Profile);yield return Click(input,"partMove");yield return PartDialogClick(input,"inventoryMoveTarget:Car:"+game.Profile.SelectedCar.instanceId);yield return Click(input,"dialogAddmove");Check(shell.Root.Q("blockPreparationMode:Reuse")!=null&&game.CartCount==0,"Owned block Move uses the same preparation before staging");yield return Click(input,"dialogCancel");Check(movedBefore==JsonUtility.ToJson(game.Profile)&&game.CartCount==0,"Cancelling owned block preparation leaves the current engine intact");yield return Click(input,"partBack");
            var raw=new PartCartLine{action=CartAction.Move,assetId=owned.AssetId,definitionId=owned.Definition.id};var staged=BlockPreparation.Build(game.Profile,game.Profile.SelectedCar.instanceId,raw,game.CartLines,BlockPreparationMode.OEM,null,game.PricingPolicy);string signature=JsonUtility.ToJson(new PartCart.Lines{entries=game.CartLines.Select(l=>l.Copy()).ToList()});Check(game.StagePreparedBlock(staged,game.Profile.revision,game.Profile.SelectedCar.instanceId,signature)&&game.CartCount>1,"OEM companions stage as one identified block plan");var independent=game.CartLines.First(l=>!l.preparedBlock&&l.action==CartAction.NewSet);Check(game.EditNativeCartPurchase(independent,JsonUtility.ToJson(independent),game.Profile.SelectedCar.instanceId,false,null,1,true,Array.Empty<string>())&&independent.preparationOwner==null,"Explicit companion edits become independent cart choices");game.RemoveNativeCartLine(game.CartLines.First(l=>l.preparedBlock));Check(game.CartLines.Single()==independent&&movedBefore==JsonUtility.ToJson(game.Profile),"Removing a core clears only its automatic companions without applying the plan");game.ClearNativeCart();
